#include <stdio.h>

int main(void) {
    unsigned int value = 0x12345678u;
    const unsigned char *bytes = (const unsigned char *)&value;

    printf("object size: %zu bytes\n", sizeof value);
    for (size_t i = 0; i < sizeof value; ++i) {
        printf("byte[%zu] = 0x%02X\n", i, (unsigned int)bytes[i]);
    }
    return 0;
}

#include <stdint.h>
#include <stdio.h>
#include <string.h>

int main(void) {
    float value = 1.0f;

    if (sizeof value != sizeof(uint32_t)) {
        puts("float and uint32_t have different sizes on this implementation");
        return 0;
    }

    uint32_t representation;
    memcpy(&representation, &value, sizeof representation);
    printf("copied %zu representation bytes\n", sizeof representation);
    printf("implementation-specific bits: 0x%08X\n", (unsigned int)representation);
    return 0;
}
